#!/usr/bin/env bash
# Sourced by setup; host nginx and certificates remain operator-managed.
write_proxy_nginx_config() {
  local output="$ROOT/spaceworks-proxy.nginx.conf" names="$WEBHOST"
  [[ "$STORAGE" != 1 ]] || names+=" files.$WEBHOST"
  sed -e "s/@DOMAIN@/$WEBHOST/g" -e "s/@SERVER_NAMES@/$names/g" > "$output" <<'NGINX' || return 1
# Generated by SpaceWorks setup: nginx :80/:443 -> app :8080, bundled storage :9000; in API-only mode the website is hosted elsewhere and only the API is served here.
server {
    listen 80;
    server_name @SERVER_NAMES@;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl http2;
    server_name @DOMAIN@;
    ssl_certificate /etc/letsencrypt/live/@DOMAIN@/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/@DOMAIN@/privkey.pem;
    client_max_body_size 128m;

    # Calendar subscription URLs are bearer credentials; keep them out of logs.
    location ~ ^/api/v1/(?:public/[^/]+/(event-calendar|bookings/calendar)|admin/makerspaces/[0-9]+/maintenance/feed)/[^/]+\.ics$ {
        access_log off;
        error_log /dev/null;
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }

    location /api/v1/live/ {
        proxy_pass http://127.0.0.1:8080;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_buffering off;
        proxy_cache off;
        proxy_read_timeout 3600s;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }

    # Tenant-migration archives; the app enforces its own 20 GiB ceiling.
    location = /api/v1/admin/platform/tenant-migrations/imports {
        client_max_body_size 20g;
        proxy_read_timeout 3600s;
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }

    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }
}
NGINX
  if [[ "$STORAGE" == 1 ]]; then
    sed "s/@DOMAIN@/$WEBHOST/g" >> "$output" <<'NGINX' || return 1

server {
    listen 443 ssl http2;
    server_name files.@DOMAIN@;
    ssl_certificate /etc/letsencrypt/live/@DOMAIN@/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/@DOMAIN@/privkey.pem;
    # 20 GiB archive ceiling plus POST multipart framing; app/store policy remains authoritative.
    client_max_body_size 20481m;
    client_body_timeout 3600s;

    location / {
        proxy_pass http://127.0.0.1:9000;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_send_timeout 3600s;
        proxy_read_timeout 3600s;
        proxy_request_buffering off;
        proxy_buffering off;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
    }
}
NGINX
  fi
  chmod 644 "$output"
}

print_proxy_nginx_steps() {
  local names="$WEBHOST" certificate_names="-d $WEBHOST"
  if [[ "$STORAGE" == 1 ]]; then
    names+=" and files.$WEBHOST"
    certificate_names+=" -d files.$WEBHOST"
  fi
  printf '\nNginx steps (run these yourself; nginx must already be running with the Certbot nginx plugin installed):\n'
  printf '1) Point DNS A/AAAA for %s at this server.\n' "$names"
  printf '2) sudo certbot certonly --nginx --cert-name %s %s\n' "$WEBHOST" "$certificate_names"
  printf '3) sudo cp "%s/spaceworks-proxy.nginx.conf" /etc/nginx/conf.d/spaceworks.conf\n' "$ROOT"
  printf '   Debian sites-available users may install and enable the file there instead.\n'
  printf '4) sudo nginx -t && sudo systemctl reload nginx\n'
  printf '5) Open https://%s/api/v1/health/ to check.\n' "$WEBHOST"
}
